s=open(p).read()
s=s.replace('\t"strings"\n','\t"strconv"\n\t"strings"\n',1)
open(p,'w').write(s)
PYEOF
mise run fmt >/dev/null 2>&1; go test ./cmd/entire/cli/ -run 'TestCheckoutBranch' -count=1 -v 2>&1 | grep -E "^(---|    ---|ok|FAIL)" | head

python3 - <<'PYEOF'
p='cmd/entire/cli/resume_test.go'
s=open(p).read()
s=s.replace('''	for _, ref := range []string{"-b evil", "@{-1}", "..", "feature/../../etc", "feature\\nmore"} {''','''	// Not "@{-1}": `check-ref-format --branch` resolves it to the previous
	// branch and reports it valid, which is git's own feature rather than
	// something this guard should override.
	for _, ref := range []string{"-b evil", "..", "feature/../../etc", "feature\\nmore"} {''',1)
open(p,'w').write(s)
PYEOF
mise run fmt >/dev/null 2>&1; go test ./cmd/entire/cli/ -run 'Branch|Checkout|Resume|ReviewTarget' -count=1 2>&1 | grep -E "^(--- FAIL|ok|FAIL)" | head
